package com.xjtu.iron.idempotent.api.repository;import java.time.*;public final class IdempotencySuccessRequest{private final String namespace,key,ownerToken,resultPayload;private final long version;private final Duration recordTtl;private final Instant now;public IdempotencySuccessRequest(String namespace,String key,String ownerToken,long version,String resultPayload,Duration recordTtl,Instant now){this.namespace=namespace;this.key=key;this.ownerToken=ownerToken;this.version=version;this.resultPayload=resultPayload;this.recordTtl=recordTtl;this.now=now;}public String getNamespace(){return namespace;}public String getKey(){return key;}public String getOwnerToken(){return ownerToken;}public long getVersion(){return version;}public String getResultPayload(){return resultPayload;}public Duration getRecordTtl(){return recordTtl;}public Instant getNow(){return now;}}
